        if not merged_done and a_start == i and b_start == j:
            new_load = load[ri] + load[rj]
            if new_load <= cap:
                new_route = routes[ri][::-1] + routes[rj]
                routes[ri] = new_route
                load[ri] = new_load
                active[rj] = False
                for v in routes[rj]:
                    route_of[v] = ri
                routes[rj] = []
                merged_done = True

    routes = [routes[i] for i in range(len(routes)) if active[i] and routes[i]]

    assigned = set()
    for r in routes:
        for v in r:
            assigned.add(v)
    unassigned = [v for v in all_customers if v not in assigned]

    # If we have too many routes, merge deterministically when feasible.
    def active_count():
        return len(routes)

    def try_merge_once():
        nonlocal routes
        best = None  # (cost_delta, a, b, new_route_a, new_route_b_deleted)
        if len(routes) <= 1:
            return False
        for a in range(len(routes)):
            ra = routes[a]
            la = route_load(ra)
            if la > cap:
                continue
            a0, a1 = ra[0], ra[-1]
            for b in range(len(routes)):
                if a == b:
                    continue
                rb = routes[b]
                lb = route_load(rb)
                if lb > cap:
                    continue
                if la + lb > cap:
                    continue
                b0, b1 = rb[0], rb[-1]
                # orientations with feasibility (no capacity issue beyond la+lb)
                candidates = []
                candidates.append(ra + rb)
                candidates.append(ra + rb[::-1])
                candidates.append(ra[::-1] + rb)
                candidates.append(ra[::-1] + rb[::-1])
                base = route_cost(ra) + route_cost(rb)
                for mroute in candidates:
                    # Only accept if merge really connects ends to ends; allow always here for simplicity.
                    newc = base - route_cost(mroute)
                    if best is None or newc > best[0]:
                        best = (newc, a, b, mroute)
        if best is None:
            return False
        _, a, b, mroute = best
        routes[a] = mroute
        del routes[b]
        return True

    while active_count() > max_veh:
        if not try_merge_once():
            break

    # Insert unassigned customers into best feasible routes (or create new).
    for v in unassigned:
        best = None  # (delta_cost, route_index, pos)
        for ri in range(len(routes)):
            if route_load(routes[ri]) + demands[v] > cap:
                continue
            ins = best_insertion(routes[ri], v)
            if ins is None:
                continue
            delta, pos = ins
            if best is None or delta < best[0]:
                best = (delta, ri, pos)
        if best is None:
            if len(routes) < max_veh:
                routes.append([v])
            else:
                # fallback: put into the route with smallest overflow (should rarely happen)
                ri = 0
                min_over = None
                for k in range(len(routes)):
                    ov = route_load(routes[k]) + demands[v] - cap
                    if min_over is None or ov < min_over:
                        min_over = ov
                        ri = k
                routes[ri].append(v)
        else:
            _, ri, pos = best
            routes[ri] = routes[ri][:pos] + [v] + routes[ri][pos:]

    # Repair capacity infeasibility by splitting overloaded routes deterministically.
    def split_route_by_capacity(route):
        if not route:
            return [[]]
        new_routes = []
        cur = []
        cur_load = 0
        for v in route:
            d = demands[v]
            if d > cap:
                # impossible to be feasible; still keep as single
                if cur:
                    new_routes.append(cur)
                    cur = []
                    cur_load = 0
                new_routes.append([v])
                continue
            if cur_load + d <= cap:
                cur.append(v)
                cur_load += d
            else:
                new_routes.append(cur)
                cur = [v]
                cur_load = d
        if cur:
            new_routes.append(cur)
        return new_routes

    fixed = []
    for r in routes:
        if route_load(r) <= cap:
            fixed.append(r)
        else:
            for nr in split_route_by_capacity(r):
                if nr:
                    fixed.append(nr)
    routes = fixed

    # If still too many routes, attempt to relocate customers from later routes into earlier feasible ones.
    def relocate_to_reduce_routes():
        nonlocal routes
        changed = False
        i = 0
        while i < len(routes) and len(routes) > max_veh:
            if not routes[i]:
                del routes[i]
                continue
            # try move customers out of route j>i into route i
            j = i + 1
            while j < len(routes) and len(routes) > max_veh:
                if not routes[j]:
                    del routes[j]
                    continue
                moved_any = False
                # attempt to move a single customer v from routes[j] into some route <=i..j-1
                best_move = None  # (delta_cost, to_route, from_route, idx_in_from, pos_in_to)
                for idx_in_from, v in enumerate(routes[j]):
                    # try insertion into any earlier feasible route
                    for to in range(0, j):
                        if route_load(routes[to]) + demands[v] > cap:
                            continue
                        ins = best_insertion(routes[to], v)
                        if ins is None:
                            continue
                        delta, pos = ins
                        # rough prefer cheaper
                        if best_move is None or delta < best_move[0]:
                            best_move = (delta, to, j, idx_in_from, pos)
                if best_move is not None:
                    _, to, fromr, idx_in_from, pos = best_move
                    v = routes[fromr][idx_in_from]
                    routes[to] = routes[to][:pos] + [v] + routes[to][pos:]
                    del routes[fromr][idx_in_from]
                    if not routes[fromr]:
                        routes[fromr] = []
                    moved_any = True
                    changed = True
                    if not routes[fromr]:
                        del routes[fromr]
                    else:
                        j = max(j, to + 1)
                if not moved_any:
                    j += 1
            i += 1
        return changed

    while len(routes) > max_veh:
        if not relocate_to_reduce_routes():
            break

    # Local improvements: intra-route 2-opt.
    def two_opt(route):
        m = len(route)
        if m < 4:
            return route
        best_route = route[:]
        best_c = route_cost(best_route)
        improved = True
        while improved:
            improved = False
            for i in range(m - 3):
                for k in range(i + 2, m - 1):
                    # reverse segment i+1..k
                    cand = best_route[:i + 1] + best_route[i + 1:k + 1][::-1] + best_route[k + 1:]
                    # capacity invariant holds (same nodes)
                    cc = route_cost(cand)
                    if cc + 1e-9 < best_c:
                        best_c = cc
                        best_route = cand
                        improved = True
                        break
                if improved:
                    break
        return best_route

    routes = [two_opt(r) for r in routes]

